def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import sys, os

    # Ensure we are working with a list of strings
    normalized = []
    for item in cmd:
        if isinstance(item, bytes):
            try:
                normalized.append(item.decode(sys.getfilesystemencoding()))
            except Exception:
                normalized.append(item.decode('utf-8', errors='replace'))
        else:
            normalized.append(str(item))

    # If we are on Windows, adjust for shebang scripts
    if sys.platform.startswith('win'):
        if not normalized:
            return tuple(normalized)

        first = normalized[0]
        # If first element points to a file with a shebang, we replace the
        # interpreter with the current Python executable
        if os.path.isfile(first):
            try:
                with open(first, 'rb') as fp:
                    first_line = fp.readline()
                if first_line.startswith(b'#!'):
                    # Replace the interpreter with sys.executable
                    normalized = [sys.executable] + normalized[1:]
            except OSError:
                # Ignore any I/O errors; keep the original command
                pass

    return tuple(normalized)<|return|>

