        for name, value in vars(self).items():
            if name.startswith('_') or any(name == r[0] for r in result):
                continue
            doc = getattr(value, '__doc__', None) or ''
            if doc is None:
                doc = ''
            result.append((name, doc))
    return result<|return|>

