def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # The class is expected to expose its interface names via a class attribute
    # called `INTERFACE` (or an analogous attribute).  If such an attribute
    # does not exist, we fall back to an empty list.
    interface = getattr(self.__class__, 'INTERFACE', [])
    if isinstance(interface, (set, frozenset)):
        interface = list(interface)
    elif isinstance(interface, dict):
        interface = list(interface.keys())
    elif not isinstance(interface, (list, tuple)):
        interface = []

    if all:
        # Include interface names from parent classes as well
        names = set(interface)
        for cls in self.__class__.__mro__[1:]:
            parent_int = getattr(cls, 'INTERFACE', [])
            if isinstance(parent_int, (set, frozenset)):
                names.update(parent_int)
            elif isinstance(parent_int, dict):
                names.update(parent_int.keys())
            elif isinstance(parent_int, (list, tuple)):
                names.update(parent_int)
        return sorted(names)
    return sorted(interface)<|return|>

