def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for arg in sequence:
        # If the argument looks like a Declaration (has an 'interfaces' attribute)
        if hasattr(arg, "interfaces"):
            # Treat the whole declaration as a single entity
            output.append(arg)
        # If the argument is a tuple, recursively expand its members
        elif isinstance(arg, tuple):
            _normalizeargs(list(arg), output)
        # Otherwise, assume it is an individual interface or implements spec
        else:
            output.append(arg)

    return output<|return|>

def _normalizeargs(sequence, output=None):
