    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []
    for item in sequence:
        if isinstance(item, tuple):
            # Expand tuples into individual arguments
            output.extend(item)
        elif hasattr(item, "__iter__") and not isinstance(item, (str, bytes)):
            # Expand iterables (e.g., Declaration objects that are iterable)
            output.extend(item)
        else:
            output.append(item)
    return output<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    # If the sequence is an iterable (but not a string/bytes), recurse
    if isinstance(sequence, (list, tuple)):
        for item in sequence:
            _normalizeargs(item, output)
    else:
        # Append everything else as a single item
        output.append(sequence)

    return output<|return|>

