    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context
    self.context = {}

    # Reinitialize bins
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        # If an initial value is defined, reset each existing bin to that value
        if isinstance(self.bins, dict):
            for key in self.bins:
                self.bins[key] = self.initial_value
        else:
            # Assume sequence type
            self.bins = [self.initial_value] * len(self.bins)
    else:
        # No initial value – rebuild the bins from scratch
        self.bins = self.make_bins()<|return|>

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # If the object does not keep any error information, return an empty list.
    if not hasattr(self, "errors"):
        return []

    indices = []

    # Errors can be stored in different formats:
    #   - as a dict with keys 'coord' and 'index'
    #   - as a list or tuple where the second item is the coordinate name
    #   - any other iterable we can inspect.
    for err in self.errors:
        if isinstance(err, dict):
            if err.get("coord") == coord_name and "index" in err:
                indices.append(err["index"])
        elif isinstance(err, (list, tuple)) and len(err) >= 2:
            # Assume the format is (index, coord, ...)
            if err[1] == coord_name:
                indices.append(err[0])

    return indices<|return|>

def _get_err_indices(self, coord_name):
