def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, lvl):
        result = {}
        for key, val in a.items():
            if key not in b:
                result[key] = val
            else:
                other_val = b[key]
                if isinstance(val, dict) and isinstance(other_val, dict):
                    if lvl == 0:
                        # Don't recurse deeper, treat as difference if values differ
                        if val != other_val:
                            result[key] = val
                    else:
                        # Recursively compute difference for sub-dictionaries
                        sub_lvl = lvl - 1 if lvl > 0 else lvl
                        subdiff = _diff(val, other_val, sub_lvl)
                        if subdiff:
                            result[key] = subdiff
                else:
                    if val != other_val:
                        result[key] = val
        return result

    return _diff(d1, d2, level)<|return|>

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    import copy

    def _diff(sub1, sub2, current_level):
        out = {}
        for key, val1 in sub1.items():
            if key not in sub2:
                # Key only in d1, include it
                out[key] = val1 if not isinstance(val1, dict) else val1
            else:
                val2 = sub2[key]
                # Determine if we should recurse
                if (
                    isinstance(val1, dict)
                    and isinstance(val2, dict)
                    and (current_level != 0)
                ):
                    next_level = (
                        current_level - 1 if current_level > 0 else -1
                    )
                    subdiff = _diff(val1, val2, next_level)
                    if subdiff:
                        out[key] = subdiff
                else:
                    if val1 != val2:
                        # Return a deep copy for mutable types to avoid side‑effects
                        out[key] = (
                            copy.deepcopy(val1)
                            if isinstance(val1, (list, dict, set))
                            else val1
                        )
        return out

    return _diff(d1, d2, level)<|return|>

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1, if a key is present both in *d1* and
    *d2* but has different values, it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(a, b, lvl):
        res = {}
        for key, val in a.items():
            if key not in b:
                # key only in d1, include it
                res[key] = val.copy() if isinstance(val, dict) else val
            else:
                val_b = b[key]
                if val == val_b:
                    continue
                if isinstance(val, dict) and isinstance(val_b, dict):
                    # both are dicts, recurse if depth allows
                    if lvl != 0:
                        sub_lvl = lvl - 1 if lvl > 0 else -1
                        sub_res = _diff(val, val_b, sub_lvl)
                        if sub_res:
                            res[key] = sub_res
                    else:
                        # depth reached, include the whole subdict from d1
                        res[key] = val.copy() if isinstance(val, dict) else val
                else:
                    # values differ and not both dicts, include d1's value
                    res[key] = val
        return res

    return _diff(d1, d2, level)<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    import re
    # Simple regexes; adjust as needed
    key_re = re.compile(r'^[A-Za-z][A-Za-z0-9_]*$')
    val_re = re.compile(r'^[A-Za-z][A-Za-z0-9_]*$')

    errors = []

    def add_error(label, msg):
        errors.append({str(label): msg})

    for key, value in labels.items():
        # Validate key
        if isinstance(key, str):
            if not key_re.match(key):
                add_error(key, f"Label key '{key}' does not match the regex [...]")
        else:
            add_error(key, 'expected string or bytes-like object')

        # Validate value(s)
        # If the value is a list, validate each element
        if isinstance(value, list):
            for val in value:
                if isinstance(val, str):
                    if not val_re.match(val):
                        add_error(val, f"Label value '{val}' does not match the regex [...]")
                else:
                    add_error(val, 'expected string or bytes-like object')
        else:
            if isinstance(value, str):
                if not val_re.match(value):
                    add_error(value, f"Label value '{value}' does not match the regex [...]")
            else:
                add_error(value, 'expected string or bytes-like object')

    if errors:
        raise ValidationError(errors)
    return None<|return|>

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    # Ensure labels is a dict
    if not isinstance(labels, dict):
        raise ValidationError([{"labels": "must be a dict"}])

    errors = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            # Assume RE_LABEL_KEY is a compiled regex for label keys
            try:
                if not RE_LABEL_KEY.match(key):
                    errors.append(
                        {key: f"Label key '{key}' does not match the regex {RE_LABEL_KEY.pattern}"}
                    )
            except NameError:
                # If the regex is not defined, skip regex check
                pass

        # Validate value type
        if isinstance(value, list):
            # Lists are not allowed as values; treat as a type error
            errors.append({repr(key): "expected string or bytes-like object"})
        elif not isinstance(value, (str, bytes)):
            errors.append({repr(key): "expected string or bytes-like object"})
        else:
            # Assume RE_LABEL_VALUE is a compiled regex for label values
            try:
                if not RE_LABEL_VALUE.match(value):
                    errors.append(
                        {repr(key): f"Label value '{value}' does not match the regex {RE_LABEL_VALUE.pattern}"}
                    )
            except NameError:
                # If the regex is not defined, skip regex check
                pass

    if errors:
        raise ValidationError(errors)<|return|>

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
