def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the app has a spec and a manifest
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        raise AttributeError("The application must have a 'spec.manifest' attribute")
    manifest = app.spec.manifest

    # Ensure the application has a dictionary to hold observer schemas
    if not hasattr(app, "observer_schema"):
        app.observer_schema = {}

    for resource_name, resource_def in manifest.items():
        # Skip resources that already have a custom observer schema
        if resource_name in app.observer_schema:
            continue

        # Build a very simple default schema based on the presence of common keys
        default_schema = {
            "type": "object",
            "properties": {},
            "required": [],
        }

        if isinstance(resource_def, dict):
            for key, val in resource_def.items():
                if key in ("metadata", "spec", "status"):
                    default_schema["properties"][key] = {"type": "object"}
                    default_schema["required"].append(key)

        # Store the generated schema
        app.observer_schema[resource_name] = default_schema
        # Optionally, log or warn that a default was created
        # (logging omitted for brevity)<|return|>

