def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""

        # collect all digests in manifest
        manifest_digests = set()
        missing_files = []

        for mf in manifest_files:
            digest = mf.get('digest')
            if not digest:
                missing_files.append(mf.get('path', str(mf)))
                continue
            manifest_digests.add(digest)

        if missing_files:
            raise ValueError(
                f"Missing digest value for files: {', '.join(missing_files)}"
            )

        # any digest required that is not in manifest
        missing_in_manifest = set(digests_used) - manifest_digests
        if missing_in_manifest:
            raise ValueError(
                f"Digests needed but not present in manifest: "
                f"{', '.join(missing_in_manifest)}"
            )

        # any digest present in manifest that is never used
        unused_in_use = manifest_digests - set(digests_used)
        if unused_in_use:
            raise ValueError(
                f"Digests present in manifest but never used: "
                f"{', '.join(unused_in_use)}"
