        # Keys are digests
        present = set(manifest_files.keys())
    else:
        # Assume an iterable of (filename, digest) tuples or objects with a 'digest' attribute
        present = set()
        for item in manifest_files:
            if isinstance(item, (list, tuple)) and len(item) == 2:
                present.add(item[1])
            else:
                # Fallback for objects that expose a .digest attribute
                dig = getattr(item, 'digest', None)
                if dig is not None:
                    present.add(dig)

    # Find missing and unused digests
    missing = used - present
    unused = present - used

    if missing:
        raise ValueError(
            "Missing digests in manifest: " + ", ".join(sorted(missing))
        )
    if unused:
        raise ValueError(
            "Unexpected digest(s) in manifest not referenced: "
