def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Check that prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator instance")

    # Ensure the prior inventory represents an earlier version
    if getattr(prior, "version", None) is None or getattr(self, "version", None) is None:
        raise ValueError("Both inventories must have a 'version' attribute")
    if prior.version >= self.version:
        raise ValueError(
            f"Prior inventory version {prior.version} must be older than current version {self.version}"
        )

    # IDs must match to qualify as the same inventory evolving over time
    if getattr(prior, "id", None) != getattr(self, "id", None):
        raise ValueError(
            f"Prior inventory id '{prior.id}' does not match current inventory id '{self.id}'"
        )

    # Basic subset check: all entries in the prior inventory should exist in the current one
    prior_entries = getattr(prior, "entries", {})
    current_entries = getattr(self, "entries", {})
    for key, prior_entry in prior_entries.items():
        if key not in current_entries:
            raise ValueError(
                f"Entry '{key}' present in prior inventory is missing from the current inventory"
            )
        current_entry = current_entries[key]

        # Optionally compare non‑version fields to ensure consistency
        # If the entries are simple data containers we compare their __dict__ without the 'version' attribute
        prior_dict = getattr(prior_entry, "__dict__", {})
        current_dict = getattr(current_entry, "__dict__", {})
        # Ignore version differences
        prior_dict = {k: v for k, v in prior_dict.items() if k != "version"}
        current_dict = {k: v for k, v in current_dict.items() if k != "version"}
        if prior_dict != current_dict:
            raise ValueError(
                f"Entry '{key}' differs between prior and current inventory (excluding version)"
            )<|return|>

