def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is iterable and convert to a set for quick lookup
    try:
        known_files = set(manifest_files)
    except TypeError:
        raise TypeError("manifest_files should be an iterable of file paths")

    # Basic structure checks: the fixity element must contain 'file' children
    if not hasattr(fixity, 'findall'):
        raise TypeError("fixity must be an XML element-like object with 'findall' method")

    file_elements = fixity.findall('.//file')
    if not file_elements:
        raise ValueError("No <file> elements found inside <fixity> block")

    # Check each file element
    for f in file_elements:
        href = f.get('href')
        if href is None:
            raise ValueError("A <file> element is missing a required 'href' attribute")
        if href not in known_files:
            raise ValueError(f"Fixity references unknown file '{href}' not present in the manifest")

    # Optionally, disallow any unexpected tags inside <fixity>
    allowed_child_tags = {'file', 'checksum', 'verified'}
    for child in fixity:
        if child.tag not in allowed_child_tags:
            raise ValueError(f"Unexpected tag <{child.tag}> inside <fixity> block")

    return True<|return|>

