        raise ValueError("The fixity block must be a dictionary.")
    if not hasattr(manifest_files, "__iter__"):
        raise ValueError("manifest_files must be an iterable of filenames.")

    manifest_set = set(manifest_files)

    # Ensure every entry in the fixity block refers to a file in the manifest
    for fn, info in fixity.items():
        if fn not in manifest_set:
            raise ValueError(f"Fixity entry refers to unknown file '{fn}' not in manifest.")
        if not isinstance(info, dict):
            raise ValueError(f"Fixity entry for '{fn}' must be a dictionary of attributes.")
        # Example sanity checks for typical fields; add as needed
        if 'hash' not in info:
            raise ValueError(f"Fixity entry for '{fn}' missing 'hash' field.")
        if 'type' not in info:
