def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # First find all XML files to get the relevant basenames
    xml_bases = set()
    for entry in os.listdir(folder):
        path = os.path.join(folder, entry)
        if os.path.isfile(path):
            base, ext = os.path.splitext(entry)
            if ext.lower() == ".xml":
                xml_bases.add(base)

    data = {}
    # Now collect all files that share the same basename as an XML file
    for entry in os.listdir(folder):
        path = os.path.join(folder, entry)
        if os.path.isfile(path):
            base, ext = os.path.splitext(entry)
            if base in xml_bases:
                # Initialise dict for this base if needed
                if base not in data:
                    data[base] = {}
                data[base][ext.lower()] = path

    return data<|return|>

