def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    prefix = ' ' * (indent * 4)
    parts = [prefix + f'{self.__class__.__name__}(']
    # Represent attributes
    attrs = []
    for key, value in self.__dict__.items():
        if isinstance(value, list):
            attrs.append(f'{key}=[{len(value)} items]')
        else:
            attrs.append(f'{key}={repr(value)}')
    if attrs:
        parts.append(prefix + '  ' + ', '.join(attrs))
    # Include children if iterable
    if hasattr(self, '__iter__') and not isinstance(self, (str, bytes, bytearray)):
        for child in self:
            parts.append(child.pretty(indent + 1, debug))
    parts.append(prefix + ')')
    return '\n'.join(parts)<|return|>

