def get_versions():
    """Get version information or return default if unable to do so."""
    # Try importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version, PackageNotFoundError
        return version(__name__.split('.')[0])
    except Exception:
        pass
    # Fallback to pkg_resources for older Python
    try:
        import pkg_resources
        return pkg_resources.get_distribution(__name__.split('.')[0]).version
    except Exception:
        pass
    # Fallback to reading a VERSION file in the same directory
    try:
        import os
        path = os.path.join(os.path.dirname(__file__), 'VERSION')
        with open(path, 'r', encoding='utf-8') as vf:
            return vf.read().strip()
    except Exception:
        pass
    # Default if all else fails
    return '0.0.0'<|return|>

