def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    def _iter_objects(node):
        """Yield node and all descendants."""
        yield node
        # Attempt to iterate over potential children containers
        for attr in ('children', 'elements', 'objs', 'items'):
            container = getattr(node, attr, None)
            if container:
                try:
                    for child in container:
                        yield from _iter_objects(child)
                except TypeError:
                    # Not iterable, ignore
                    pass
        # Try __iter__ if node is itself iterable and not a basic type
        try:
            if not isinstance(node, (str, bytes)):
                for child in node:
                    yield from _iter_objects(child)
        except TypeError:
            pass

    num_objects = 0
    good_objects = 0

    for obj in _iter_objects(self):
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # Assume each object provides an `is_valid` or `validate` method
                if hasattr(obj, "is_valid"):
                    is_valid = bool(obj.is_valid())
                elif hasattr(obj, "validate"):
                    obj.validate()
                    is_valid = True
                else:
                    # No validation method, assume valid
                    is_valid = True
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Object {obj!r} failed validation: {exc}")

        if check_digests:
            try:
                if hasattr(obj, "check_digest"):
                    digest_ok = bool(obj.check_digest())
                else:
                    # No digest method, assume OK
                    digest_ok = True
                if not digest_ok:
                    is_valid = False
            except Exception as exc:
                digest_ok = False
                is_valid = False
                if show_warnings:
                    print(f"Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        def _traverse(obj):
            nonlocal num_objects, good_objects
            num_objects += 1
            ok = True

            if validate_objects:
                try:
                    ok = bool(obj.validate())
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        print(f"Warning: validation failed for {obj}: {exc}")

            if check_digests and hasattr(obj, "check_digest"):
                try:
                    digest_ok = bool(obj.check_digest())
