                        ok = False
                        if show_warnings:
                            print(f"Warning: digest check failed for {obj}")
                except Exception as exc:
                    ok = False
                    if show_warnings:
                        print(f"Warning: digest check failed for {obj}: {exc}")

            if ok:
                good_objects += 1

            for child in obj:
                _traverse(child)

        _traverse(self)
        return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Use a stack to perform depth‑first traversal of the hierarchy.
    stack = [self]
    while stack:
        obj = stack.pop()
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested.
        if validate_objects:
            validate_method = getattr(obj, "validate", None)
            if callable(validate_method):
                try:
                    validate_method()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        obj_id = getattr(obj, "id", repr(obj))
                        print(f"Warning: validation failed for object {obj_id}: {exc}")
            else:
                if show_warnings:
                    obj_id = getattr(obj, "id", repr(obj))
                    print(f"Warning: object {obj_id} has no validate() method")

        # Check the digest if requested.
        if check_digests:
            digest_method = getattr(obj, "check_digest", None)
            if callable(digest_method):
                try:
                    digest_method()
                except Exception as exc:
                    is_valid = False
                    if show_warnings:
                        obj_id = getattr(obj, "id", repr(obj))
                        print(f"Warning: digest check failed for object {obj_id}: {exc}")
            else:
                if show_warnings:
                    obj_id = getattr(obj, "id", repr(obj))
                    print(f"Warning: object {obj_id} has no check_digest() method")

        if is_valid:
            good_objects += 1

        # If the object can contain sub‑objects, add them to the stack.
        # The presence of an __iter__/iterable interface is assumed.
        try:
            for child in obj:
                stack.append(child)
        except TypeError:
            # obj is not iterable; nothing to do.
            pass

    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    def _recurse(node):
        nonlocal num_objects, good_objects
        num_objects += 1
        ok = True

        if validate_objects:
            try:
                node.is_valid()
            except Exception as e:
                ok = False
                if show_warnings:
                    print(f"Validation error in {node!r}: {e}")

        if check_digests:
            try:
                node.check_digest()
            except Exception as e:
                ok = False
                if show_warnings:
                    print(f"Digest error in {node!r}: {e}")

        if ok:
            good_objects += 1

        for child in node:
            _recurse(child)

    _recurse(self)
    return num_objects, good_objects<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
        """Validate storage root hierarchy.

        Returns:
            num_objects - number of objects checked
            good_objects - number of objects checked that were found to be valid
        """
        num_objects = 0
        good_objects = 0

        # Walk through all elements in the hierarchy.  The storage class
        # should provide an iterator over its children; if not, we fall back
        # to a breadth‑first traversal that checks for common containers.
        try:
            iterator = iter(self)
        except TypeError:
            # Fallback: try to traverse known container attributes
            def fallback_iter():
                for attr in ['children', 'elements', 'tokens']:
                    if hasattr(self, attr):
                        for child in getattr(self, attr):
                            yield child
            iterator = fallback_iter()

        for element in iterator:
            num_objects += 1
            element_ok = True

            # Validate the element itself, if requested.
            if validate_objects and hasattr(element, "validate"):
                try:
                    element_ok = element.validate()
                except Exception as exc:
                    element_ok = False
                    if show_warnings:
                        print(f"[WARNING] Validation error on {element}: {exc}")

            # Additional digest check
            if check_digests and hasattr(element, "check_digest"):
                try:
                    digest_ok = element.check_digest()
                    if not digest_ok:
                        element_ok = False
                        if show_warnings:
                            print(f"[WARNING] Digest mismatch on {element}")
                except Exception as exc:
                    element_ok = False
                    if show_warnings:
                        print(f"[WARNING] Digest check failed on {element}: {exc}")

            if element_ok:
                good_objects += 1

        return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
