        except OSError as exc:
            raise RuntimeError(f"Failed to create OCFL root directory at {self.path}") from exc

    # Create the ocfl-index marker file if it does not exist
    index_marker = os.path.join(self.path, "__index__")
    if not os.path.exists(index_marker):
        try:
            with open(index_marker, "w", encoding="utf-8") as f:
                f.write("OCFL root\n")
        except OSError as exc:
            raise RuntimeError(f"Failed to create ocfl-index marker at {index_marker}") from exc

    # Initialise an empty inventory JSON file
    inventory_file = os.path.join(self.path, "inventory.json")
    if not os.path.exists(inventory_file):
        inventory = {
            "ocfl": {
                "root": os.path.basename(self.path),
                "objects": []
            }
        }
        try:
            with open(inventory_file, "w", encoding="utf-8") as f:
                json.dump(inventory, f, indent=2)
        except OSError as exc:
            raise RuntimeError(f"Failed to write inventory file at {inventory_file}") from exc

    # Store the path of the created inventory for later reference
    self.inventory_path = inventory_file

    # Optionally, set up any required default metadata or structure
    # (this can be expanded by subclasses or other initialisation steps)<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Helper to load inventory files, expecting a simple format: <digest> <filename>
    def _load_inventory(path):
        inventory = {}
        if not os.path.exists(path):
            raise FileNotFoundError(f"Inventory file not found: {path}")
        with open(path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                parts = line.split(None, 1)
                if len(parts) != 2:
                    continue
                digest, fname = parts
                inventory[fname] = digest
        return inventory

    # Load the root inventory once
    if not hasattr(self, 'root_inventory') or self.root_inventory is None:
        root_path = os.path.join(self.root_dir, 'inventory.xml')
        self.root_inventory = _load_inventory(root_path)

    # Keep a list of digests that differ from the root
    if not hasattr(self, 'different_digests'):
        self.different_digests = []

    for v_dir in version_dirs:
        inv_path = os.path.join(v_dir, 'inventory.xml')
        inv = _load_inventory(inv_path)

        for fname, digest in inv.items():
            root_digest = self.root_inventory.get(fname)
            if root_digest is not None and root_digest != digest:
                self.different_digests.append(
                    (fname, v_dir, root_digest, digest)
                )

    return self.different_digests<|return|>

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a container for per‑version inventories and a place for digest mismatches
    if not hasattr(self, "_version_inventories"):
        self._version_inventories = {}
    if not hasattr(self, "_mismatched_digests"):
        self._mismatched_digests = {}

    # Helper to read an inventory file into a mapping of path → digest
    def _load_inventory(inv_path):
        inv = {}
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                for line in f:
                    # Assuming inventory format: <path> <digest>
                    parts = line.strip().split(None, 1)
                    if len(parts) == 2:
                        inv[parts[0]] = parts[1]
        except OSError as exc:
            raise FileNotFoundError(f"Could not read inventory '{inv_path}': {exc}")
        return inv

    # Load the root inventory once for comparison
    root_inv_path = os.path.join(self.root_dir, "inventory.xml")
    root_inventory = _load_inventory(root_inv_path)

    for idx, vd in enumerate(version_dirs, start=1):
        inv_path = os.path.join(vd, "inventory.xml")
        # 1. inventory must exist
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory.xml in version directory '{vd}'.")
        inv = _load_inventory(inv_path)
        self._version_inventories[idx] = inv

        # 2. inventory of this version must contain every entry that was present in all previous versions
        for prev_idx in range(1, idx):
            prev_inv = self._version_inventories.get(prev_idx, {})
            for path, digest in prev_inv.items():
                if path not in inv or inv[path] != digest:
                    raise ValueError(
                        f"Entry '{path}' from version {prev_idx} is missing or mismatched "
                        f"in inventory of '{vd}'. Expected digest '{digest}'."
                    )

        # 3. record any digest differences compared to the root inventory
        mismatches = []
        for path, digest in inv.items():
            root_digest = root_inventory.get(path)
            if root_digest is not None and root_digest != digest:
                mismatches.append(path)
        if mismatches:
            self._mismatched_digests[vd] = mismatches

    # Store a consolidated view of mismatches if needed elsewhere
    self._summary_mismatches = self._mismatched_digests.copy()<|return|>

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path

    p = Path(path)

    if not p.exists():
        return f"path not found: {p}"
    if p.is_file():
        return "file"

    # Directory: start checks for known markers
    # 1. Storage root marker files
    if (p / ".ocfl-root").exists() or (p / "root").exists() or (p / "README").exists():
        return "root"

    # 2. Look for 0=* files (Namaste files)
    for nm_file in p.glob("0=*"):
        try:
            content = nm_file.read_text().strip().lower()
        except Exception as e:
            return f"error reading {nm_file}: {e}"
        if "root" in content:
            return "root"
        if "object" in content:
            return "object"
        if "file" in content:
            return "file"
        return f"unknown marker file {nm_file.name}: {content}"

    # 3. Fallback: could be an object if it contains 'inventory' or similar
    if (p / "inventory").exists() or (p / "inventory.json").exists():
        return "object"

    return f"unclassified directory: {p}"<|return|>

