    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    from pathlib import Path

    p = Path(path)

    if not p.exists():
        return f'not found: {p}'

    if p.is_file():
        return 'file'

    if p.is_dir():
        try:
            # Scan the directory for files starting with "0="
            for entry in p.iterdir():
                if entry.is_file() and entry.name.startswith('0='):
                    return 'object'
        except PermissionError as exc:
            return f'permission error: {exc}'
        except OSError as exc:
            return f'os error: {exc}'

        return 'root'

    return f'unknown type: {p}'
