        try:
            import argcomplete
            # borgmatic ships a function that returns the top-level ArgumentParser,
            # but if it doesn't exist we just return an empty script indicating
            # that completion could not be generated.
            try:
                from borgmatic.cli import get_parser
                parser = get_parser()
            except Exception:
                return "# borgmatic completion could not be generated: no argparse parser available."
            return argcomplete.get_script(parser)
