def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    import re
    from urllib.parse import urlencode, urlparse, urlunparse, parse_qs, quote_plus

    # Replace placeholders like {key}
    placeholder_pat = re.compile(r'\{(\w+)\}')
    used_keys = set()

    def _placeholder_repl(match):
        key = match.group(1)
        if key not in url_args:
            raise KeyError(f"Missing URL argument: {key}")
        used_keys.add(key)
        return quote_plus(str(url_args[key]))

    new_url = placeholder_pat.sub(_placeholder_repl, url)

    # Append any remaining args as query parameters
    remaining = {k: v for k, v in url_args.items() if k not in used_keys}
    if remaining:
        # Merge with existing query string
        parsed = urlparse(new_url)
        query_params = parse_qs(parsed.query)
        for k, v in remaining.items():
            # parse_qs returns lists; keep consistency
            query_params[k] = [str(v)]
        new_query = urlencode(query_params, doseq=True)
        new_url = urlunparse(
            (parsed.scheme, parsed.netloc, parsed.path, parsed.params, new_query, parsed.fragment)
        )

    return new_url<|return|>

