def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None

    freq_str = frequency.strip()
    if not freq_str or freq_str.lower() == 'always':
        return None

    import re
    pattern = r'^\s*([0-9]+(?:\.[0-9]+)?)\s*([a-zA-Z]+)\s*$'
    match = re.match(pattern, freq_str)
    if not match:
        raise ValueError(f'Invalid frequency string: {frequency}')

    amount_str, unit = match.groups()
    amount = float(amount_str)

    unit = unit.lower()
    kwargs = {}

    if unit in ('day', 'days'):
        kwargs['days'] = amount
    elif unit in ('week', 'weeks'):
        kwargs['weeks'] = amount
    elif unit in ('hour', 'hours'):
        kwargs['hours'] = amount
    elif unit in ('minute', 'minutes', 'min', 'mins'):
        kwargs['minutes'] = amount
    elif unit in ('second', 'seconds', 'sec', 'secs'):
        kwargs['seconds'] = amount
    elif unit in ('month', 'months'):
        # approximate as 30 days
        kwargs['days'] = amount * 30
    elif unit in ('year', 'years'):
        # approximate as 365 days
        kwargs['days'] = amount * 365
    else:
        raise ValueError(f'Unknown time unit in frequency: {unit}')

    return datetime.timedelta(**kwargs)<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency == "always":
        return None

    import re
    freq = frequency.strip()
    match = re.match(r'^\s*(\d+)\s*(\w+)\s*$', freq, re.IGNORECASE)
    if not match:
        raise ValueError(f"Cannot parse frequency: {frequency}")

    number = int(match.group(1))
    unit = match.group(2).lower()

    if unit in ("day", "days", "d"):
        return datetime.timedelta(days=number)
    if unit in ("week", "weeks", "w"):
        return datetime.timedelta(weeks=number)
    if unit in ("hour", "hours", "h"):
        return datetime.timedelta(hours=number)
    if unit in ("minute", "minutes", "m"):
        return datetime.timedelta(minutes=number)
    if unit in ("second", "seconds", "s"):
        return datetime.timedelta(seconds=number)

    raise ValueError(f"Unknown time unit: {unit}")<|return|>

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    if host in ('localhost', '127.0.0.1', '::1'):
        return True
    try:
        for res in socket.getaddrinfo(host, None):
            family, _, _, _, sockaddr = res
            address = sockaddr[0]
            if family == socket.AF_INET and address.startswith('127.'):
                return True
            if family == socket.AF_INET6 and address == '::1':
                return True
    except socket.gaierror:
        return False
    return False<|return|>

