    """
    # Attempt to grab a named group for the variable name.  Fallback to the first group.
    var_name = None
    try:
        var_name = matcher.group('name')
    except Exception:
        pass
    if not var_name:
        try:
            var_name = matcher.group(1)
        except Exception:
            raise ValueError("Matcher does not contain a variable name")

    # Attempt to grab a default value group.  Fallback to the second group.
    default_val = None
    try:
        default_val = matcher.group('default')
    except Exception:
        pass
    if default_val is None:
        try:
            default_val = matcher.group(2)
        except Exception:
            pass

    if var_name in os.environ:
        return os.environ[var_name]
    if default_val is not None:
        return default_val
    raise RuntimeError(f"Environment variable '{var_name}' not found and no default value was provided.")<|return|>

