def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Ensure commands is a list
    if isinstance(commands, str):
        commands = [commands]
    elif not isinstance(commands, (list, tuple)):
        raise TypeError("commands must be a string or a list/tuple of strings")

    # Ensure args is a list; if None, treat as empty
    if args is None:
        args = []

    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple of argument strings")

    results = []

    for cmd in commands:
        # Build the full command list: command plus any arguments
        # If cmd itself includes spaces, split it; otherwise treat as one token
        if isinstance(cmd, str):
            # If cmd is a simple word without spaces, use as is; else split at whitespace
            if ' ' in cmd:
                cmd_tokens = cmd.split()
            else:
                cmd_tokens = [cmd]
        else:
            raise TypeError("each command must be a string")

        full_cmd = cmd_tokens + list(args)

        if verbose:
            print(f"Running command: {' '.join(full_cmd)}")

        # Set up stderr handling
        stderr = subprocess.DEVNULL if hide_stderr else None

        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=stderr,
                text=True,
                check=True
            )
            results.append(result)
        except subprocess.CalledProcessError as exc:
            if verbose:
                print(f"Command failed: {exc}", file=sys.stderr)
            # Re-raise to allow caller to handle
            raise

    # Return a single CompletedProcess if only one command, else list of results
    return results[0] if len(results) == 1 else results<|return|>

