def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    parsed_configs = {}
    error_records = []

    # Logger for creating LogRecord objects
    logger = logging.getLogger(__name__)

    def _resolve_env_in_obj(obj):
        """Recursively resolve environment variables in strings within dict/list."""
        if isinstance(obj, dict):
            for k, v in obj.items():
                if isinstance(v, str):
                    obj[k] = os.path.expandvars(v)
                else:
                    _resolve_env_in_obj(v)
        elif isinstance(obj, list):
            for i, item in enumerate(obj):
                if isinstance(item, str):
                    obj[i] = os.path.expandvars(item)
                else:
                    _resolve_env_in_obj(item)

    for filename in config_filenames:
        try:
            # Load file
            with open(filename, 'r', encoding='utf-8') as fh:
                content = fh.read()

            # Attempt JSON first
            try:
                import json
                config = json.loads(content)
            except Exception:
                # Fallback to YAML
                try:
                    import yaml
                    config = yaml.safe_load(content)
                except Exception:
                    # If not JSON/YAML, treat entire content as string
                    config = content

            # Apply overrides
            if overrides and isinstance(config, dict):
                config.update(overrides)

            # Resolve environment variables
            if resolve_env and isinstance(config, (dict, list)):
                _resolve_env_in_obj(config)

            parsed_configs[filename] = config

        except Exception as exc:
            # Create a LogRecord for the error
            record = logger.makeRecord(
                name=logger.name,
                level=logging.ERROR,
                fn='',
                lno=0,
                msg=f"Failed to load configuration '{filename}': {exc}",
                args=(),
                exc_info=None,
            )
            error_records.append(record)

    return parsed_configs, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
    - dict of configuration filename to corresponding parsed configuration,
    - sequence of logging.LogRecord instances containing any parse errors.
    """
    import os
    import json
    try:
        import yaml
        _yaml = yaml
    except Exception:
        _yaml = None

    configs = {}
    errors = []

    logger = logging.getLogger('config_loader')
    logger.setLevel(logging.ERROR)

    env_pattern = re.compile(r'\$\{([^}^{]+)\}')

    def resolve_env_vars(text):
        if not isinstance(text, str):
            return text
        def replace(match):
            return os.getenv(match.group(1), '')
        return env_pattern.sub(replace, text)

    def merge_overrides(target, overrides_dict):
        if not isinstance(overrides_dict, dict):
            return target
        for k, v in overrides_dict.items():
            if isinstance(v, dict) and isinstance(target.get(k), dict):
                merge_overrides(target[k], v)
            else:
                target[k] = v
        return target

    for path in config_filenames:
        record = None
        try:
            with open(path, 'r', encoding='utf-8') as fp:
                raw = fp.read()
            # Resolve environment variables
            if resolve_env:
                raw = resolve_env_vars(raw)
            # Detect format by extension
            ext = os.path.splitext(path)[1].lower()
            if _yaml and ext in {'.yaml', '.yml'}:
                config = _yaml.safe_load(raw)
            elif ext == '.json':
                config = json.loads(raw)
            else:
                # Try JSON, fallback to YAML
                try:
                    config = json.loads(raw)
                except Exception:
                    if _yaml:
                        config = _yaml.safe_load(raw)
                    else:
                        raise ValueError(f"Unsupported config format for file {path}")
            if not isinstance(config, dict):
                raise ValueError(f"Top-level config must be a dictionary in file {path}")
            # Apply overrides
            if overrides is not None:
                merge_overrides(config, overrides)
            configs[path] = config
        except Exception as exc:
            # Create a LogRecord manually
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=path,
                lineno=0,
                msg=str(exc),
                args=(),
                exc_info=exc.__traceback__
            )
            errors.append(record)

    return configs, errors<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import logging
    import os

    try:
        import yaml
    except ImportError:
        # yaml not available; return empty configuration and error record
        logger = logging.getLogger('config')
        error = logging.LogRecord('config', logging.ERROR, '', 0,
                                  "yaml module not available for configuration parsing", None, None)
        return {}, [error]

    parsed_configs = {}
    error_records = []

    if overrides is None:
        overrides = {}

    for config_file in config_filenames:
        try:
            with open(config_file, 'r', encoding='utf-8') as fh:
                config_data = yaml.safe_load(fh)

            if config_data is None:
                config_data = {}

            if not isinstance(config_data, dict):
                raise ValueError(f"Configuration file '{config_file}' must contain a mapping at the top level")

            # Apply overrides (overwriting keys if present)
            for key, value in overrides.items():
                if key in config_data:
                    config_data[key] = value

            # Resolve environment variables in string values
            if resolve_env:
                for k, v in config_data.items():
                    if isinstance(v, str):
                        config_data[k] = os.path.expandvars(v)

            parsed_configs[config_file] = config_data

        except Exception as exc:
            # Create a LogRecord for the error
            rec = logging.LogRecord('config', logging.ERROR, config_file, 0,
                                    f"Error parsing configuration file '{config_file}': {exc}",
                                    (), None)
            error_records.append(rec)

    return parsed_configs, error_records<|return|>

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re
    config_map = {}
    errors = []

    def _resolve_env_variables(obj):
        if isinstance(obj, dict):
            return {k: _resolve_env_variables(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_variables(v) for v in obj]
        elif isinstance(obj, str):
            return re.sub(r'\$\{([^}]+)\}',
                          lambda m: os.getenv(m.group(1), ''),
                          obj)
        return obj

    for filename in config_filenames:
        try:
            with open(filename, 'r') as f:
                cfg = json.load(f)
        except Exception as e:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration file '{filename}': {e}",
                args=None,
                exc_info=e
            )
            errors.append(record)
            continue

        if overrides and isinstance(overrides, dict):
            cfg.update(overrides)

        if resolve_env:
            try:
                cfg = _resolve_env_variables(cfg)
            except Exception as e:
                record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=filename,
                    lineno=0,
                    msg=f"Failed to resolve environment variables in configuration file '{filename}': {e}",
                    args=None,
                    exc_info=e
                )
                errors.append(record)
                continue

        config_map[filename] = cfg

    return config_map, errors<|return|>

