def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise TypeError("Parameter seq cannot be None")

    from collections.abc import Sequence as _Sequence
    # Treat string and bytes as sequences of characters/bytes
    if isinstance(seq, _Sequence):
        sequence = seq
    else:
        try:
            sequence = list(seq)
        except TypeError:
            raise TypeError(f"Cannot convert {seq!r} to a sequence")

    # Determine the element type based on the first item of the sequence.
    # If the sequence is empty, type is NoneType.
    if sequence:
        element_type = type(sequence[0])
    else:
        element_type = type(None)

    return sequence, element_type<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Handle None
    if seq is None:
        return (None, type(seq))

    # If it's already a sequence type we can return it untouched
    if isinstance(seq, (list, tuple, set)):
        return (seq, type(seq))

    # Strings and bytes – optionally split into chunks
    if isinstance(seq, (str, bytes)):
        if bufsize is not None and isinstance(bufsize, int) and bufsize > 0:
            # Create a generator that yields slices of the string/bytes
            def _chunker(s=seq, n=bufsize):
                for i in range(0, len(s), n):
                    yield s[i:i + n]
            return (_chunker(), type(seq))
        else:
            # Default: materialise as a list of characters / bytes
            return (list(seq), type(seq))

    # General iterable – try to materialise it as a list
    try:
        seq_list = list(seq)
        return (seq_list, type(seq))
    except TypeError:
        # Not iterable – return as is
        return (seq, type(seq))<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq already behaves like a sequence (has length and indexing), return it as-is.
    if hasattr(seq, "__len__") and hasattr(seq, "__getitem__"):
        return seq, type(seq)

    # Try to consume the iterable into a list.
    try:
        seq_list = list(seq)
    except TypeError:
        raise ValueError("Input must be a sequence or an iterable")

    return seq_list, type(seq_list)<|return|>

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Known sequence types
    if isinstance(seq, (list, tuple, set, frozenset)):
        sequence = list(seq)
        seq_type = type(seq).__name__
    # Strings – optionally chunk into pieces of *bufsize*
    elif isinstance(seq, str):
        if bufsize:
            sequence = [seq[i:i + bufsize] for i in range(0, len(seq), bufsize)]
        else:
            sequence = list(seq)
        seq_type = 'str'
    # Bytes – optionally chunk into pieces of *bufsize*
    elif isinstance(seq, bytes):
        if bufsize:
            sequence = [seq[i:i + bufsize] for i in range(0, len(seq), bufsize)]
        else:
            sequence = list(seq)
        seq_type = 'bytes'
    # Anything else – treat as a single element sequence
    else:
        sequence = [seq]
        seq_type = type(seq).__name__
    return sequence, seq_type<|return|>

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before,
    it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram
    one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Helper: compute current scale from histogram data
    def _compute_scale():
        if hasattr(self, "bins"):
            if isinstance(self.bins, dict):
                return sum(self.bins.values())
            else:
                return sum(self.bins)
        return 0

    # If no target scale is given, just return (or compute) the current scale
    if other is None:
        if not hasattr(self, "scale") or self.scale is None or recompute:
            self.scale = _compute_scale()
        return self.scale

    # A target scale was supplied, perform a rescale
    target_scale = float(other)
    current_scale = getattr(self, "scale", None)
    if current_scale is None:
        current_scale = _compute_scale()
    if current_scale == 0:
        raise LenaValueError(
            "Cannot rescale histogram with zero scale"
        )
    factor = target_scale / current_scale

    # Apply scaling factor to the underlying data structure
    if hasattr(self, "bins"):
        if isinstance(self.bins, dict):
            for k in list(self.bins):
                self.bins[k] *= factor
        else:
            self.bins = [x * factor for x in self.bins]

    # Update stored scale
    self.scale = target_scale
    return self.scale<|return|>

