def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from inspect import getfullargspec
    from zope.interface import Invalid, providedBy
    errors = []

    # 1. Check that the candidate declares it provides the interface
    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(
                "candidate does not provide interface '%s'" % iface.__name__
            )

    # Helper to collect method signature info
    def _signature_ok(iface_sig, cand_sig):
        iface_args = list(iface_sig.args)
        cand_args = list(cand_sig.args)
        # strip 'self' from instance methods
        if iface_args and iface_args[0] == 'self':
            iface_args = iface_args[1:]
        if cand_args and cand_args[0] == 'self':
            cand_args = cand_args[1:]
        # compare positional arguments, varargs, varkw, defaults
        if iface_args != cand_args:
            return False
        if iface_sig.varargs != cand_sig.varargs:
            return False
        if iface_sig.varkw != cand_sig.varkw:
            return False
        if iface_sig.defaults != cand_sig.defaults:
            return False
        return True

    # 2. Verify required methods
    if hasattr(iface, "_required_methods"):
        for name in iface._required_methods:
            impl = getattr(candidate, name, None)
            if impl is None:
                errors.append(
                    "candidate does not define required method '%s'" % name
                )
                continue
            if not callable(impl):
                errors.append(
                    "attribute '%s' is not callable" % name
                )
                continue
            try:
                iface_sig = iface._methods[name]
            except AttributeError:
                # If interface is a dynamic one without stored signatures
                iface_sig = None
            # if we have signature info, compare
            if iface_sig is not None:
                cand_sig = getfullargspec(impl)
                if not _signature_ok(iface_sig, cand_sig):
                    errors.append(
                        "signature mismatch for method '%s': "
                        "expected %s got %s" % (
                            name,
                            iface_sig,
                            cand_sig
                        )
                    )

    # 3. Verify required attributes
    if hasattr(iface, "_required_attrs"):
        for name in iface._required_attrs:
            if not hasattr(candidate, name):
                errors.append(
                    "candidate does not define required attribute '%s'" % name
                )

    # 4. Report collected errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid(errors)

    return True<|return|>

