    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine the type to check against the interface
    cand_type = candidate if isinstance(candidate, type) else type(candidate)

    # Quick subclass check
    try:
        if issubclass(cand_type, iface):
            return True
    except TypeError:
        # iface may not be a class; fall back to attribute check
        pass

    # If interface is a protocol-like object, verify that all attributes exist
    try:
        if all(hasattr(cand_type, attr) for attr in dir(iface) if not attr.startswith('_')):
            return True
    except Exception:
        # In case iface is something else, continue
        pass

    # If tentative, simply return False on failure
    if tentative:
