    # Accept both classes and instances.  `iface` is expected to be a class or
    # an abstract base class that the candidate should implement.
    if candidate is None:
        if tentative:
            return False
        else:
            raise TypeError("candidate is None")

    # Determine the proper test depending on whether we have a class
    # or an instance to test.
    if isinstance(candidate, type):
        ok = issubclass(candidate, iface)
