def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Basic sanity checks
    if not isinstance(iface, type):
        raise TypeError("`iface` must be a class (an interface)")
    if candidate is None:
        message = "candidate is None, cannot provide interface %s" % iface.__name__
        if tentative:
            return False
        raise ValueError(message)

    # Resolve the target class (support instances or class objects)
    target_cls = candidate if isinstance(candidate, type) else candidate.__class__

    # If it is already a subclass, we consider it valid
    if issubclass(target_cls, iface):
        return True

    # Gather all callable attributes that must be implemented
    required_methods = [
        name for name, member in vars(iface).items()
        if callable(member) and not name.startswith("_")
    ]
    # Sometimes methods are defined on the class but not in vars() (e.g., inherited)
    required_methods += [
        name for name in dir(iface)
        if callable(getattr(iface, name)) and not name.startswith("_")
        and name not in required_methods
    ]

    # Find missing methods on the target
    missing = [name for name in required_methods if not hasattr(target_cls, name)]

    if missing:
        if tentative:
            return False
        raise ValueError(
            f"Class `{target_cls.__name__}` does not implement methods required by "
            f"interface `{iface.__name__}`: {', '.join(missing)}"
        )
    return True<|return|>

