    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it immediately.
    if explicit_mc is not None:
        return explicit_mc

    # Collect the metaclasses of all base classes.
    mcs = set()
    for b in bases:
        mcs.add(type(b))

    # If no bases or all bases are new‑style and default to 'type'.
    if not mcs:
        return type

    # If only one distinct metaclass, return it.
    if len(mcs) == 1:
        return next(iter(mcs))

    # Attempt to find a common most‑derived metaclass.
    for candidate in mcs:
        if all(issubclass(candidate, other) for other in mcs):
            return candidate

    # No compatible metaclass could be found.
    raise TypeError(
        "metaclass conflict: cannot choose a common metaclass for "%
        ", ".join(mc.__name__ for mc in mcs)
    )<|return|>

def determineMetaclass(bases, explicit_mc=None):
