    # If there are no bases, default to type
    if not bases:
        return type

    # Gather all metaclasses of the bases
    metaclasses = set(type(b) for b in bases)

    # If there's only one metaclass, use it
    if len(metaclasses) == 1:
        return metaclasses.pop()

    # If there are multiple metaclasses, raise an error
    raise TypeError(
