def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, eg https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Default NodeInfo document path
    if document_path is None:
        document_path = "/.well-known/nodeinfo/2.0"

    # Normalize paths to avoid double slashes
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    base = url.rstrip("/")

    href = base + document_path

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/1.0",
                "href": href
            }
        ]
    }<|return|>

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    # Parse the document if it is a string
    if isinstance(doc, str):
        try:
            xml_root = etree.fromstring(doc)
        except Exception as exc:
            raise ValueError("Invalid XML document") from exc
    else:
        xml_root = doc

    # Find the Signature element if not provided
    if signature is None:
        sig_elem = xml_root.find(".//{http://www.w3.org/2000/09/xmldsig#}Signature")
        if sig_elem is None:
            raise ValueError("No Signature element found in the document")
    else:
        sig_elem = signature

    # Verify the signature using the provided public key
    verifier = XMLVerifier()
    try:
        verifier.verify(sig_elem, x509_cert=public_key, key=public_key)
    except Exception as exc:
        raise RuntimeError(f"Signature verification failed: {exc}") from exc

    return True
