def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    doc = document.strip()
    # Try JSON format first
    if doc.startswith('{') or doc.startswith('['):
        try:
            data = json.loads(doc)
        except Exception as e:  # noqa: BLE001
            raise ValueError('Invalid JSON webfinger') from e
        if not isinstance(data, dict):
            raise ValueError('JSON webfinger must be an object')
        return data

    # Otherwise assume XRD (XML)
    try:
        root = ElementTree.fromstring(doc)
    except Exception as e:  # noqa: BLE001
        raise ValueError('Invalid XRD webfinger') from e

    ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
    subject_el = root.find('xrd:Subject', ns)
    subject = subject_el.text if subject_el is not None else None

    aliases = [
        alias_el.text
        for alias_el in root.findall('xrd:Alias', ns)
        if alias_el.text
    ]

    links = []
    for link_el in root.findall('xrd:Link', ns):
        links.append(
            {
                'rel': link_el.attrib.get('rel'),
                'type': link_el.attrib.get('type'),
                'href': link_el.attrib.get('href'),
            }
        )

    return {'subject': subject, 'aliases': aliases, 'links': links}<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).
    """
    doc_strip = document.strip()
    # First try JSON parsing
    if doc_strip.startswith('{') or doc_strip.startswith('['):
        try:
            return json.loads(doc_strip)
        except Exception:
            pass  # Fall back to XRD

    # Try to parse as XRD (XML)
    try:
        root = ET.fromstring(doc_strip)
    except Exception as e:
        raise ValueError("Unable to parse webfinger document as JSON or XRD") from e

    # Helper to find elements possibly namespaced
    def _find(tag):
        namespace = None
        if '}' in root.tag:
            namespace = root.tag.split('}')[0].strip('{')
        if namespace:
            return root.find(f'{{{namespace}}}{tag}')
        return root.find(tag)

    # Extract subject
    subj_elem = _find('Subject')
    subject = subj_elem.text.strip() if subj_elem is not None and subj_elem.text else None

    # Extract aliases
    alias_elems = root.findall('Alias')
    if not alias_elems:
        # try with namespace
        alias_elems = root.findall(f'.//{{{namespace}}}Alias') if namespace else []
    aliases = [a.text.strip() for a in alias_elems if a.text] if alias_elems else []

    # Extract links
    link_elems = root.findall('Link')
    if not link_elems:
        link_elems = root.findall(f'.//{{{namespace}}}Link') if namespace else []
    links = []
    for le in link_elems:
        # Copy attributes into a dict
        link = {k.strip(): v.strip() for k, v in le.attrib.items()}
        if le.text:
            link['text'] = le.text.strip()
        links.append(link)

    return {'subject': subject, 'aliases': aliases, 'links': links}<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET
    from typing import Dict

    doc = document.strip()
    if not doc:
        raise ValueError('empty WebFinger document')

    # If looks like JSON
    if doc[0] in ('{', '['):
        try:
            return json.loads(doc)
        except json.JSONDecodeError as exc:
            raise ValueError('Invalid JSON WebFinger document') from exc

    # Otherwise assume XRD (XML)
    try:
        root = ET.fromstring(doc)
    except ET.ParseError as exc:
        raise ValueError('Invalid XRD WebFinger document') from exc

    def _strip_ns(tag: str) -> str:
        return tag.split('}', 1)[-1] if '}' in tag else tag

    def _elem_to_dict(elem) -> Dict:
        result = {}
        # Include attributes if any
        if elem.attrib:
            for k, v in elem.attrib.items():
                result[k] = v
        # Recurse for child elements
        for child in elem:
            key = _strip_ns(child.tag)
            if len(child) > 0:
                value = _elem_to_dict(child)
            else:
                value = child.text or ''
            # Handle multiple occurrences
            if key in result:
                if isinstance(result[key], list):
                    result[key].append(value)
                else:
                    result[key] = [result[key], value]
            else:
                result[key] = value
        return result

    return { _strip_ns(root.tag): _elem_to_dict(root) }<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try parsing as JSON first (the new format)
    try:
        import json
        return json.loads(document)
    except Exception:  # pragma: no cover - fallback to XRD parsing
        # Fallback: try to parse as XRD (old format)
        try:
            import xml.etree.ElementTree as ET

            # The XRD namespace defined by the Diaspora webfinger specification
            NS = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}

            root = ET.fromstring(document)

            subject = root.findtext("xrd:Subject", namespaces=NS)
            aliases = [el.text for el in root.findall("xrd:Alias", namespaces=NS)]

            links = []
            for link_el in root.findall("xrd:Link", namespaces=NS):
                link_info = {
                    "rel": link_el.get("rel"),
                    "type": link_el.get("type"),
                    "href": link_el.get("href"),
                }
                links.append(link_info)

            return {"subject": subject, "aliases": aliases, "links": links}
        except Exception as exc:  # pragma: no cover - parsing failure
            raise ValueError(f"Unable to parse Diaspora webfinger document: {exc}") from exc<|return|>

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Import modules locally to avoid top‑level imports
    try:
        import json
        data = json.loads(document)
    except (ValueError, TypeError):  # not JSON – try XRD
        try:
            import xml.etree.ElementTree as ET
            from typing import Dict
        except ImportError as exc:
            raise ValueError("Required library for XRD parsing not available.") from exc

        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}
        try:
            root = ET.fromstring(document)
        except ET.ParseError as exc:
            raise ValueError("Invalid XRD document.") from exc

        result: Dict = {}
        result['subject'] = root.findtext('xrd:Subject', namespaces=ns)
        result['aliases'] = [e.text for e in root.findall('xrd:Alias', namespaces=ns)]
        properties = {}
        for prop in root.findall('xrd:Property', namespaces=ns):
            term = prop.attrib.get('term')
            if term:
                properties[term] = prop.text
        result['properties'] = properties
        result['links'] = []
        for link in root.findall('xrd:Link', namespaces=ns):
            result['links'].append({
                'rel': link.attrib.get('rel'),
                'href': link.attrib.get('href')
            })
        return result

    # Handle the JSON case
    from typing import Dict
    result: Dict = {}
    result['subject'] = data.get('subject')
    result['aliases'] = data.get('aliases', [])
    result['properties'] = data.get('properties', {})
    # Normalize links into a flat list of dicts containing 'rel' and 'href'
    result['links'] = []
    for link in data.get('links', []):
        rel = link.get('rel')
        href = link.get('href')
        if rel is not None and href is not None:
            result['links'].append({'rel': rel, 'href': href})
    return result<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import urllib.request, urllib.parse, urllib.error

    # Build the resource identifier
    if handle.startswith('acct:'):
        acct = handle
    else:
        acct = f'acct:{handle}'
    try:
        # Extract domain part for the hostname
        domain = handle.split('@', 1)[1]
    except IndexError:
        return None

    # Construct the URL
    resource = urllib.parse.quote(acct, safe='')
    url = f'https://{domain}/.well-known/webfinger?resource={resource}'

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            return resp.read().decode('utf-8')
    except (urllib.error.URLError, urllib.error.HTTPError, ValueError):
        return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails."""
    try:
        import urllib.parse
        import urllib.request
        import ssl

        # Expect handle in the form "acct:user@example.com" or "user@example.com"
        if handle.lower().startswith("acct:"):
            acct = handle
        else:
            if "@" not in handle:
                return None
            acct = f"acct:{handle}"
        # Extract host for the URL
        _, host = acct.split(":", 1)
        if "@" not in host:
            return None
        _, domain = host.split("@", 1)

        resource = urllib.parse.quote(acct)
        url = f"https://{domain}/.well-known/webfinger?resource={resource}"
        ctx = ssl.create_default_context()
        with urllib.request.urlopen(url, context=ctx, timeout=5) as resp:
            return resp.read().decode("utf-8")
    except Exception:
        return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    from urllib.request import urlopen, Request
    from urllib.error import URLError, HTTPError

    try:
        domain = handle.split('@')[1]
    except Exception:
        return None

    url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
    req = Request(url, headers={'Accept': 'application/json'})
    try:
        with urlopen(req, timeout=5) as resp:
            return resp.read().decode('utf-8')
    except (URLError, HTTPError):
        return None<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.

    Arguments:
        handle (str): The account handle, e.g. 'user@example.com'

    Returns:
        Optional[str]: The webfinger document as string, or None if retrieval failed.
    """
    try:
        at_index = handle.find('@')
        if at_index == -1:
            return None
        acct = f'acct:{handle}'
        domain = handle[at_index + 1 :]
        url = f'https://{domain}/.well-known/webfinger?resource={acct}'
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status >= 400:
                return None
            return resp.read().decode('utf-8')
    except Exception:
        return None<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import requests
    from urllib.parse import quote

    if not handle:
        raise ValueError("handle must not be empty")

    # Form the webfinger URL
    if '@' in handle:
        # handle is in the form user@domain
        local, domain = handle.split('@', 1)
        resource = f"acct:{handle}"
        url = f"https://{domain}/.well-known/webfinger?resource={quote(resource)}"
    else:
        # assume handle is a domain
        resource = f"acct:{handle}"
        url = f"https://{handle}/.well-known/webfinger?resource={quote(resource)}"

    try:
        resp = requests.get(url, timeout=10)
    except requests.RequestException as exc:
        raise ConnectionError(f"Unable to retrieve webfinger from {url}: {exc}") from exc

    if resp.status_code != 200:
        raise ConnectionError(f"Webfinger request to {url} failed with status {resp.status_code}")

    try:
        data = resp.json()
    except ValueError as exc:
        raise ValueError(f"Failed to parse JSON from {url}: {exc}") from exc

    return data<|return|>

def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import urllib.request
    import urllib.parse
    import json

    if "@" not in handle:
        raise ValueError(f"handle '{handle}' must be of the form acct:user@domain")

    acct, domain = handle.split("@", 1)
    resource = f"acct:{handle}"
    query = urllib.parse.urlencode({"resource": resource})
    url = f"https://{domain}/.well-known/webfinger?{query}"

    try:
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(
                    f"HTTP error {resp.status} retrieving webfinger for {handle}"
                )
            data = resp.read()
            return json.loads(data)
    except urllib.error.HTTPError as e:
        raise RuntimeError(
            f"HTTP error {e.code} retrieving webfinger for {handle}"
        ) from e
    except urllib.error.URLError as e:
        raise RuntimeError(
            f"URL error retrieving webfinger for {handle}"
        ) from e
    except json.JSONDecodeError as e:
        raise ValueError(
            f"Invalid JSON in webfinger response for {handle}"
        ) from e<|return|>

def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    # Construct the well‑known host‑meta URL
    url = host.rstrip('/') + '/.well-known/host-meta'
    try:
        import urllib.request, urllib.error
    except Exception as exc:
        raise ImportError("urllib is required to retrieve host‑meta") from exc

    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            # Ensure HTTP 200
            if response.getcode() != 200:
                raise ValueError(f"Failed to retrieve host‑meta from {host}: HTTP {response.getcode()}")
            xml_data = response.read()
    except urllib.error.HTTPError as he:
        raise ValueError(f"HTTP error retrieving host‑meta from {host}: {he.code}") from he
    except Exception as e:
        raise ValueError(f"Error retrieving host‑meta from {host}: {e}") from e

    # Attempt to parse the response as an XRD object
    try:
        # XRD is expected to provide a class method for parsing from string
        return XRD.fromstring(xml_data)
    except Exception:
        # Fallback to ElementTree if XRD parser is unavailable
        import xml.etree.ElementTree as ET
        return ET.fromstring(xml_data)<|return|>

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    url = f"https://{host}/.well-known/host-meta"
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.exceptions.RequestException as exc:
        raise ValueError(f"Unable to retrieve host-meta from {host}") from exc
    try:
        return XRD(response.content)
    except Exception as exc:
        raise ValueError(f"Failed to parse XRD from host-meta at {host}") from exc<|return|>

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        req_func = getattr(requests, method.lower())
    except AttributeError:
        return (None, ValueError(f"Unsupported HTTP method: {method}"))
    try:
        response = req_func(url, data=data, timeout=timeout, *args, **kwargs)
        return (response.status_code, None)
    except Exception as e:
        return (None, e)<|return|>

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Interpret spec_option as an iterable of filename extensions or a single extension string.
    file_names = []
    for directory in settings_dirs:
        try:
            for entry in os.listdir(directory):
                # Skip directories; only consider files
                full_path = os.path.join(directory, entry)
                if not os.path.isfile(full_path):
                    continue

                # Filter by spec_option if provided
                if spec_option:
                    if isinstance(spec_option, (list, tuple, set)):
                        # accept if any extension matches
                        if not any(entry.lower().endswith(ext.lower()) for ext in spec_option):
                            continue
                    elif isinstance(spec_option, str):
                        if not entry.lower().endswith(spec_option.lower()):
                            continue

                file_names.append(full_path)
        except OSError:
            # Skip directories that cannot be accessed
            continue
    return file_names<|return|>

