def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    files = []
    for d in settings_dirs:
        if not os.path.isdir(d):
            continue
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for entry in entries:
            path = os.path.join(d, entry)
            if not os.path.isfile(path):
                continue
            if spec_option:
                if isinstance(spec_option, str):
                    # simple extension match
                    if not entry.endswith(spec_option):
                        continue
                elif isinstance(spec_option, (list, tuple)):
                    if not any(entry.endswith(ext) for ext in spec_option):
                        continue
                else:
                    try:
                        import re
                        if not re.search(spec_option, entry):
                            continue
                    except Exception:
                        continue
            files.append(path)
    return files<|return|>

