def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files."""
        include = parser_dict.get('include')
        if not include:
            return []

        resolved = []

        def _flatten(value, base_path=None):
            if isinstance(value, dict):
                for key, sub_value in value.items():
                    path = f"{base_path}.{key}" if base_path else key
                    _flatten(sub_value, path)
            elif isinstance(value, list):
                for item in value:
                    _flatten(item, base_path)
            else:
                # Assume a flag or string indicating that this group should be included
                if value is True or isinstance(value, str):
                    resolved.append(base_path)

        _flatten(include)
        return resolved<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # Grab the include directive; it may be a list, a single string, or absent
    includes = parser_dict.pop("include", [])
    if isinstance(includes, (str, bytes)):
        includes = [includes]
    if not isinstance(includes, list):
        # If it's something else, ignore
        includes = []

    # Recursive inclusion: for each referenced group merge its definitions
    for inc in includes:
        # If the include entry is already a dictionary, use it directly
        if isinstance(inc, dict):
            inc_dict = inc
        else:
            # Otherwise load the spec file from the include path
            inc_path = os.path.join(self.base_path, inc)
            if not os.path.exists(inc_path):
                raise FileNotFoundError(f"Included spec file '{inc_path}' not found.")
            with open(inc_path, "r", encoding="utf-8") as fp:
                inc_dict = yaml.safe_load(fp) or {}

        # Resolve includes within the included dictionary itself
        inc_dict = self._include_groups(inc_dict)

        # Merge the included dictionary into the current one
        for key, val in inc_dict.items():
            if key in parser_dict:
                # Merge dicts recursively
                if isinstance(parser_dict[key], dict) and isinstance(val, dict):
                    parser_dict[key].update(val)
                # Merge lists without duplication
                elif isinstance(parser_dict[key], list) and isinstance(val, list):
                    parser_dict[key] = list(dict.fromkeys(parser_dict[key] + val))
                else:
                    parser_dict[key] = val
            else:
                parser_dict[key] = val

    return parser_dict<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}

    # The spec may be stored on the instance or as a class attribute.
    spec = getattr(self, "SPEC", getattr(self.__class__, "SPEC", None))
    if not spec:
        return defaults

    # Iterate over the declared attributes in the spec.
    for attr, descriptor in spec.get("attributes", {}).items():
        # Prefer an explicit default if provided.
        if "default" in descriptor:
            defaults[attr] = descriptor["default"]
            continue
        # Some specs use "value" to denote a constant.
        if "value" in descriptor:
            defaults[attr] = descriptor["value"]
            continue
        # Handle callable defaults (e.g. lambda: []) safely.
        if callable(descriptor.get("default")):
            defaults[attr] = descriptor["default"]()

    return defaults<|return|>

