        # If spec is a mapping, use it directly
        if isinstance(spec, dict):
            defaults.update(spec)
        # If spec has a method to produce a dict, use that
        elif hasattr(spec, "to_dict"):
            try:
                defaults.update(spec.to_dict())
            except Exception:
