def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # The specification may provide default values for arguments
    spec = getattr(self, "spec", {})
    spec_defaults = spec.get("defaults", {})

    # Arguments supplied by the caller (e.g. via a command‑line parser)
    supplied = getattr(self, "args", {})

    # Resolve each argument: supplied value overrides spec default
