def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Retrieve the command object.  If the command is not present we raise an informative error.
    cmd = getattr(self, "commands", {}).get(command_name)
    if cmd is None:
        raise KeyError(f"Command '{command_name}' not found in the registry.")

    # Look up the option in the command's specification dictionary.  The exact attribute name may vary;
    # many implementations store options in a .options attribute.  If it does not exist, fall back
    # to .args or .parameters for robustness.
    spec = None
    for attr in ("options", "args", "parameters"):
        opt_dict = getattr(cmd, attr, None)
        if isinstance(opt_dict, dict):
            spec = opt_dict.get(argument_name)
            if spec is not None:
                break

    if spec is None:
        raise KeyError(
            f"Option '{argument_name}' not defined for command '{command_name}'."
        )

    return spec<|return|>

def get_option_spec(self, command_name, argument_name):
