    # Ensure the command exists
    if not hasattr(self, 'commands') or command_name not in self.commands:
        raise KeyError(f"Command '{command_name}' not found")
    command = self.commands[command_name]

    # Ensure the command has an options attribute (e.g., a dict)
    if not hasattr(command, 'options') or argument_name not in command.options:
        raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'")

    return command.options[argument_name]<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    # Assume ``args`` is a mapping (dict-like) where the key is the
    # argument name and the value indicates whether it is silenced.
    # For boolean values we treat ``True`` as silenced, for other
    # iterable values we consider an item of ``True`` as silencing
    # that argument, otherwise any truthy value is also considered
    # silenced.
    for key, value in args.items():
        if isinstance(value, bool):
            if value:
                silent_args.append(key)
        elif isinstance(value, (list, tuple, set)):
            if any(item is True for item in value):
                silent_args.append(key)
        else:
            if value:
                silent_args.append(key)
    return silent_args<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []

    # If args is a dict, iterate over its items
    if isinstance(args, dict):
        silent_args = [name for name, value in args.items() if value is None]
    # If args looks like a namespace (e.g., argparse.Namespace)
    elif hasattr(args, "__dict__"):
        silent_args = [name for name, value in vars(args).items() if value is None]
    else:
        # Unknown type, try to iterate provided interface
        try:
            for name, value in args:
                if value is None:
                    silent_args.append(name)
        except Exception:
            # Fallback: no silent arguments identifiable
            pass

    return silent_args<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'REQUIRED_ATTRIBS', getattr(self, 'REQUIRED', []))
    if not required:
        return True
    if args is None:
        raise ValueError("No arguments were supplied")
    if not isinstance(args, dict):
        raise TypeError("Expected args to be a dict, got %s" % type(args).__name__)
    missing = [key for key in required if key not in args]
    if missing:
        raise ValueError("Missing required arguments: %s" % ", ".join(missing))
    return True<|return|>

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    required = getattr(self, 'required_args', None)
    if required is None:
        # No required arguments defined
        return
    if not isinstance(required, (list, set, tuple)):
        raise TypeError(f"required_args must be a list, set, or tuple, got {type(required)}")

    # Handle positional arguments (list/tuple)
    if isinstance(args, (list, tuple)):
        if len(args) < len(required):
            missing = list(required)[len(args):]
            raise ValueError(f"Missing required positional arguments: {missing}")
        return

    # Handle keyword arguments (dict)
    if isinstance(args, dict):
        missing = [k for k in required if k not in args]
        if missing:
            raise ValueError(f"Missing required keyword arguments: {missing}")
        return

    # Unsupported args type
    raise TypeError("args must be a dict or list/tuple of positional arguments")<|return|>

