        if isinstance(cond, dict):
            # Expect keys like 'option' (or 'by') specifying the option that triggers the requirement,
            # and 'value' specifying its required value.
            trigger_option = cond.get('option') or cond.get('by')
            expected_value = cond.get('value')

            # Obtain the actual value from args, which could be a dict or a namespace-like object.
            if isinstance(args, dict):
                actual_value = args.get(trigger_option)
            else:
                actual_value = getattr(args, trigger_option, None)

            if actual_value == expected_value:
                required.append(opt['name'])
        else:
            # If the condition is a simple string, treat it as the name of a flag
            # that, if present, makes this option required.
            present = False
            if isinstance(args, dict):
                present = cond in args
            else:
                present = getattr(args, cond, None) is not None

            if present:
                required.append(opt['name'])

    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for opt in options_spec:
        # Each option spec may contain a 'required_when' attribute.
        req_when = opt.get('required_when')
        if not req_when:
            continue

        # Normalize to a list for uniform processing.
        if isinstance(req_when, (str, tuple)):
            conds = [req_when]
        elif isinstance(req_when, (list, tuple)):
            conds = req_when
        else:
            # Unrecognised type; skip this option.
            continue

        for cond in conds:
            if isinstance(cond, str):
                # Simple string condition matches the command name.
                if cond == command_name:
                    required_args.append(opt['name'])
                    break
            elif callable(cond):
                # Callable condition receives command_name and args.
                try:
                    if cond(command_name, args):
                        required_args.append(opt['name'])
                        break
                except Exception:
                    # If the condition raises an exception, ignore it.
                    pass
            else:
                # Unsupported condition type; ignore.
                continue
    return required_args<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    required = []

    for opt in options_spec:
        # Determine the argument name; common keys are 'name', 'id', 'arg'
        arg_name = opt.get('name') or opt.get('id') or opt.get('arg')
        if not arg_name:
            continue

        cond = opt.get('required_when')
        if cond is None:
            continue

        # Evaluate the condition, supporting callables or simple expressions.
        ok = False
        try:
            if callable(cond):
                # Assume a callable takes the args and command name
                ok = bool(cond(args, command_name))
            else:
                # Try evaluating a string expression in a sane environment
                ok = bool(eval(cond, {}, {'args': args, 'command_name': command_name}))
        except Exception:
            ok = False

        if ok:
            required.append(arg_name)

    return required<|return|>

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        for opt in options_spec:
            cond = opt.get("required_when")
            if not cond:
                continue

            # Evaluate the condition. ``cond`` may be a callable or a mapping
            # of key/value pairs that must be satisfied in ``args``.
            try:
                if callable(cond):
                    satisfied = cond(args)
                elif isinstance(cond, (dict, list, set)):
                    satisfied = True
                    # Support a dict of exact matches
                    if isinstance(cond, dict):
                        for key, val in cond.items():
                            if isinstance(val, (list, set, tuple)):
                                if args.get(key) not in val:
                                    satisfied = False
                                    break
                            else:
                                if args.get(key) != val:
                                    satisfied = False
                                    break
                    # Or a list/set of option names that must be present
                    else:
                        for key in cond:
                            if key not in args or args[key] in (None, False):
                                satisfied = False
                                break
                else:
                    # Unsupported type: treat as not satisfied
                    satisfied = False
            except Exception as exc:
                raise ValueError(
                    f"Error evaluating required_when condition for "
                    f"option '{opt.get('arg_name') or opt.get('name')}' "
                    f"in command '{command_name}': {exc}"
                ) from exc

            if satisfied:
                # Prefer the short name the user expects
                arg_name = opt.get("arg_name") or opt.get("name")
                if arg_name:
                    required.append(arg_name)

        return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Mapping of argument names to their maximum allowed length
    # Subclasses may define self.arg_lengths accordingly.
    arg_lengths = getattr(self, 'arg_lengths', {})

    # Accept a dict or any iterable of (name, value) pairs
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = args
        except TypeError:
            raise ValueError("args must be a dict or an iterable of (name, value) pairs")

    for name, value in items:
        max_len = arg_lengths.get(name)
        if max_len is None:
            continue  # no length constraint for this argument
        if value is None:
            continue  # nothing to check
        try:
            length = len(value)
        except TypeError:
            # Value has no length; skip the check
            continue
        if length > max_len:
            raise ValueError(f"Argument '{name}' length {length} exceeds maximum of {max_len}")<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dictionary")

    for name, value in args.items():
        # Determine the maximum allowed length for this argument.
        # Prefer a dedicated attribute like `max_length_<name>`.
        max_attr = f"max_length_{name}"
        allowed = getattr(self, max_attr, None)

        # Fallback to a shared mapping if available.
        if allowed is None and hasattr(self, "max_lengths"):
            allowed = self.max_lengths.get(name)

        # If there's a restriction, enforce it when the value is list-like or a string.
        if allowed is not None and hasattr(value, "__len__"):
            if len(value) > allowed:
                raise ValueError(
                    f"Argument '{name}' length {len(value)} exceeds the maximum allowed {allowed}"
                )
    return True<|return|>

