def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure the class defines a mapping of choice attributes to their allowed values
    if not hasattr(self.__class__, "CHOICES"):
        return
    for field, value in args.items():
        # Skip empty or None values
        if value in (None, ""):
            continue
        # Skip fields that are not defined as choice arguments
        if field not in self.__class__.CHOICES:
            continue
        allowed = self.__class__.CHOICES[field]
        # Allow either a single value or an iterable of values
        if isinstance(value, (list, tuple, set)):
            for val in value:
                if val not in allowed:
                    raise ValueError(
                        f"Invalid value '{val}' for argument '{field}'. "
                        f"Must be one of {allowed}."
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{field}'. "
                    f"Must be one of {allowed}."
                )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary of argument names to values")
    # Expect a mapping `self.choices` where key is arg name and value is a list or set of allowed options
    choices_def = getattr(self, 'choices', {})
    for name, val in args.items():
        if name not in choices_def:
            continue
        allowed = choices_def[name]
        if not isinstance(allowed, (list, set, tuple)):
            allowed = {allowed}
        if val not in allowed:
            raise ValueError(f"Argument '{name}' has an invalid choice: {val!r}. "
                             f"Allowed values are: {sorted(allowed)!r}.")<|return|>

def validate_choices_args(self, args):
