        # Determine mapping of argument names to available choices.
        # Prefer a 'choices' attribute if present, otherwise look for 'arg_choices'.
        if hasattr(self, "choices") and isinstance(self.choices, dict):
            choice_map = self.choices
        elif hasattr(self, "arg_choices") and isinstance(self.arg_choices, dict):
            choice_map = self.arg_choices
        else:
            choice_map = {}

        for name, value in args.items():
            if name in choice_map:
                allowed = choice_map[name]
                if value not in allowed:
                    raise ValueError(
