                    )<|return|>

def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to allowed values.
    # The mapping may be defined as a class attribute named CHOICES or
    # an instance attribute named choices.  Prefer the attribute that
    # actually exists.
    if hasattr(self, 'CHOICES'):
        allowed = self.__class__.CHOICES
    elif hasattr(self, 'choices'):
        allowed = getattr(self, 'choices')
    else:
        allowed = {}

    # Iterate over supplied arguments and validate each.
    for key, value in args.items():
        # Only validate arguments that have an entry in the allowed mapping.
        if key in allowed:
            opts = allowed[key]
            # In case the options are None or a custom callable,
            # we skip validation.
            if opts is None or callable(opts):
                continue

            # Make sure the value is among the accepted options.
            if value not in opts:
                raise ValueError(
                    f"Invalid value for '{key}': {value!r}. "
                    f"Expected one of {opts!r}."
                )<|return|>

def validate_choices_args(self, args):
