    :param args: The received arguments.
    """
    # If this instance does not define any choice restrictions, nothing to validate.
    if not hasattr(self, "choices") or not self.choices:
        return

    for arg, val in args.items():
        if arg in self.choices:
            allowed = set(self.choices[arg]) if isinstance(self.choices[arg], (list, tuple, set)) else {self.choices[arg]}

            # Handle single value or iterable of values
            if isinstance(val, (list, tuple, set)):
                for v in val:
                    if v not in allowed:
