def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the number of arguments falls within the allowed range
    if getattr(self, 'min_args', None) is not None and len(args) < self.min_args:
        raise ValueError(
            f"Expected at least {self.min_args} arguments, got {len(args)}"
        )
    if getattr(self, 'max_args', None) is not None and len(args) > self.max_args:
        raise ValueError(
            f"Expected at most {self.max_args} arguments, got {len(args)}"
        )
    return True<|return|>

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        # Determine the bound values; if not set, use +/- infinity
        min_val = getattr(self, "min", -float("inf"))
        max_val = getattr(self, "max", float("inf"))

        # Support both iterable of values and dictionary of name/value pairs
        if isinstance(args, dict):
            items = args.items()
        else:
            items = enumerate(args)

        for name, val in items:
            if not (min_val <= val <= max_val):
                raise ValueError(
                    f"Argument {name}={val} out of bounds [{min_val}, {max_val}]"
                )<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, "min", None)
    max_val = getattr(self, "max", None)

    for arg in args:
        # Handle dict-like arguments that may specify their own bounds
        if isinstance(arg, dict):
            val = arg.get("value")
            min_arg = arg.get("min", min_val)
            max_arg = arg.get("max", max_val)
        else:
            val = arg
            min_arg = min_val
            max_arg = max_val

        if min_arg is not None and val < min_arg:
            raise ValueError(
                f"Argument '{val}' below minimum '{min_arg}'."
            )
        if max_arg is not None and val > max_arg:
            raise ValueError(
                f"Argument '{val}' above maximum '{max_arg}'."
            )
    return True<|return|>

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Assume self.ARGUMENTS is a mapping of argument names to their constraints.
    # Each entry may have 'minimum' and/or 'maximum' keys.
    if not hasattr(self, "ARGUMENTS"):
        # No constraints defined; nothing to validate
        return

    for name, value in args.items():
        spec = self.ARGUMENTS.get(name, {})
        min_val = spec.get("minimum")
        max_val = spec.get("maximum")

        # Skip validation if no constraints specified
        if min_val is None and max_val is None:
            continue

        # If the value is an iterable, validate each element
        if isinstance(value, (list, tuple, set)):
            for idx, elem in enumerate(value):
                if min_val is not None and elem < min_val:
                    raise ValueError(f"Argument '{name}'[{idx}] = {elem} is below minimum {min_val}")
                if max_val is not None and elem > max_val:
                    raise ValueError(f"Argument '{name}'[{idx}] = {elem} exceeds maximum {max_val}")
            continue

        # Single value validation
        if min_val is not None and value < min_val:
            raise ValueError(f"Argument '{name}' = {value} is below minimum {min_val}")
        if max_val is not None and value > max_val:
            raise ValueError(f"Argument '{name}' = {value} exceeds maximum {max_val}")<|return|>

