def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if isinstance(args, list):
        # assume list of (key, value) tuples
        kwargs = dict(args)
    elif isinstance(args, dict):
        kwargs = args
    else:
        raise TypeError("args must be a dict or list of key/value pairs")

    control_args = {}
    nested_args = {}

    for key, value in kwargs.items():
        if key.startswith("control_"):
            control_args[key] = value
        elif key.startswith("custom_"):
            # custom args are treated as nested but with the 'custom_' prefix removed
            nested_args[key[7:]] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalise args to an iterable of key-value pairs
    if hasattr(args, 'items'):
        items = args.items()
    else:
        items = args

    for key, value in items:
        # Only consider string keys
        if not isinstance(key, str):
            continue

        if key.startswith('_'):
            # Control arguments start with underscore
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")
        if extra_vars is None:
            return vars_dict

        # If extra_vars is already a dict, merge directly
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Accept a sequence of key-value pairs or 'key=value' strings
        try:
            iterable = iter(extra_vars)
        except TypeError:
            raise TypeError(f"extra_vars must be None, a dict, or an iterable, got {type(extra_vars).__name__}")

        for item in iterable:
            if isinstance(item, dict):
                # If an item is a dict, merge its items
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                # If it's a two-element tuple/list, treat as key/value
                key, value = item
                vars_dict[key] = value
            elif isinstance(item, str) and '=' in item:
                # Parse 'key=value' string
                key, value = item.split('=', 1)
                vars_dict[key] = value
            else:
                raise ValueError(f"Cannot interpret extra_vars element: {item!r}")

        return vars_dict<|return|>

