def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Mapping of parser name to a dict of argument -> type
        def get_type_map(name):
            # Prefer a class attribute defined like <UPPER>_ARG_TYPES,
            # otherwise fall back to a global or empty dict.
            attr = getattr(self, f"{name.upper()}_ARG_TYPES", None)
            if isinstance(attr, dict):
                return attr
            # Optional fallback: a global registry if it exists
            registry = globals().get("_ARG_TYPE_MAP", {})
            return registry.get(name.lower(), {})

        type_map = get_type_map(parser_name)

        for arg, target_type in type_map.items():
            if arg not in values_dict:
                continue
            raw = values_dict[arg]
            try:
                if target_type is bool:
                    if isinstance(raw, str):
                        if raw.lower() in ("true", "1", "yes", "y"):
                            values_dict[arg] = True
                        elif raw.lower() in ("false", "0", "no", "n"):
                            values_dict[arg] = False
                        else:
                            raise ValueError(f"Cannot interpret '{raw}' as boolean")
                    else:
                        values_dict[arg] = bool(raw)
                elif target_type is int:
                    values_dict[arg] = int(raw)
                elif target_type is float:
                    values_dict[arg] = float(raw)
                elif target_type is list:
                    if isinstance(raw, str):
                        # allow comma-separated values
                        values_dict[arg] = [x.strip() for x in raw.split(",") if x.strip()]
                    elif isinstance(raw, (tuple, list)):
                        values_dict[arg] = list(raw)
                    else:
                        values_dict[arg] = [raw]
                else:
                    # Generic cast, if callable
                    if callable(target_type):
                        values_dict[arg] = target_type(raw)
                    else:
                        # Fallback: keep original
                        values_dict[arg] = raw
            except Exception as exc:  # pragma: no cover
                raise ValueError(
                    f"Error converting argument '{arg}' for parser '{parser_name}'"
                ) from exc
        return values_dict<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec
    This function looks for a plugin specification file in the
    supplied directory. It supports JSON (`plugin.json`) and
    YAML (`plugin.yaml` / `plugin.yml`) formats. The resulting
    nested dictionary is then flattened into a single level map
    where each key reflects the nested path joined by dots.

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except Exception:
        yaml = None

    # locate spec file
    spec_path = None
    for name in ("plugin.json", "plugin.yaml", "plugin.yml"):
        potential = os.path.join(plugin_dir, name)
        if os.path.isfile(potential):
            spec_path = potential
            break

    if not spec_path:
        # No spec found – return empty dict
        return {}

    # load spec content
    with open(spec_path, "r", encoding="utf-8") as f:
        if spec_path.endswith(".json"):
            try:
                data = json.load(f)
            except Exception:
                data = {}
        else:
            if yaml is None:
                # cannot load yaml, return empty dict
                data = {}
            else:
                try:
                    data = yaml.safe_load(f) or {}
                except Exception:
                    data = {}

    # flatten nested dicts
    def _flatten(d, parent_key=""):
        flat = {}
        for key, value in d.items():
            full_key = f"{parent_key}.{key}" if parent_key else key
            if isinstance(value, dict):
                flat.update(_flatten(value, full_key))
            else:
                flat[full_key] = value
        return flat

    return _flatten(data)<|return|>

