def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = "CONFIG_PATH"
    if os.environ.get(env_var) is None:
        # Use instance's config_path attribute if present; otherwise fall back to current working directory
        config_path = getattr(self, "config_path", None)
        if config_path is None:
            config_path = os.getcwd()
        os.environ[env_var] = os.path.abspath(config_path)<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = "FOLIA_CONFIG_PATH"
    if os.getenv(env_var) is None:
        os.environ[env_var] = getattr(self, "config_path", "")<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not root:
        raise ValueError("Root must not be empty")
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped = path[len(root):]
    # Remove any leading slash or backslash characters
    while stripped and stripped[0] in ('/', '\\'):
        stripped = stripped[1:]
    return stripped<|return|>

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped = path[len(root):]
    if stripped.startswith(os.sep):
        stripped = stripped[len(os.sep):]
    return stripped<|return|>

